import json, subprocess
root="/home/ross-geller/Projects/minastik/swiss-keepsakes"
pre=(f"Swiss Keepsakes prototype, owner round-2 review follow-up. Repo root {root} (no git). FIRST read docs/ux/prototype/worker-brief.md (Design skills section; build directly, no gates). "
     "Verdicts: docs/ux/prototype/screens/phase1-review/phase1-review-round2-2026-10-14.json. Current shots: docs/ux/prototype/screens/phase1-review/img/ (manifest-*.json). "
     "Shared card surface (owner-agreed): 'rounded-3xl bg-surface shadow-surface', no border; KPI/fact cards use the shared src/components/stat-card.tsx from 1.9t (see reports/1.9t.md and the Overview / P02 dashboards). "
     "Note: the owner's separate tours session is editing features/tours/** and may leave missing i18n keys that crash #/store; do not edit tours files, and if a screen you need crashes because of them, report it instead of working around it.\n")
T=[("1.13s","1.13s C15 cards on the shared shadow surface (impeccable)",5224,
 "Skill: impeccable. Owner on 1.13r: 'each card should be having the shadow pattern already existed in the code base, don't use solid border'. Target: features/transactions/order-detail/** and routes/_guest/account_.orders.$orderId.tsx. Change: every card and boxed section on C15 (pickup-ticket header, tab panels, amounts, payment rows, timeline, policy, notices other than status Alerts) uses the shared shadow surface with no solid outer border; inner separators may stay as subtle dividers where they structure content. Keep the tabs, states and behaviour from 1.13r unchanged. Ownership: those files only. Acceptance: before/after 375px EN and DE for header + each tab and 3 key states in docs/ux/prototype/screens/1.13s/; computed-style check (border width 0, box-shadow equals the M02 card); tsc on your files and eslint clean."),
 ("1.11s","1.11s M04 key facts and fulfilment money panel as standalone cards (evon)",5225,
 "Skill: evon:ui-ux. Owner on 1.11r and 1.15r: 'everything is good, except for the analytics group, pls use standalone card, not splitting them by vertical border, see the partner or merchant overview dashboard for the pattern'. Target: features/merchant/order-detail/** (the key-facts strip in the header: pickup, total, balance, source; and any similar fact or money group in FulfilmentActions / the Payments tab) and features/merchant/record-payment/** if its summary uses the same split pattern. Change: render each fact as its own StatCard-style standalone card (shared stat-card.tsx; extend it additively if needed) in a responsive grid (2 per row at 375, 4 per row from 1024), with no vertical dividers, matching Overview/P02. Everything else in M04/M08 stays as approved. Ownership: those files, stat-card.tsx additive. Acceptance: before/after 375 and 1024, EN and DE, requested order + a handed-over-with-balance order + M08 open, in docs/ux/prototype/screens/1.11s/; the 1.11r and 1.15r drives still pass; tsc on your files and eslint clean.")]
for key,title,port,body in T:
    spec=pre+body+f" Dev server port {port}. Report: docs/ux/prototype/reports/{key}.md."
    r=subprocess.run(["orca","orchestration","task-create","--spec",spec,"--task-title",title,"--display-name",title,"--deps","[]","--json"],capture_output=True,text=True)
    t=json.loads(r.stdout)["result"]; t=t.get("task",t)
    s=subprocess.run(["orca","orchestration","worker-start","--task",t["id"],"--worktree","current","--agent","claude","--model","opus","--json"],capture_output=True,text=True)
    d=json.loads(s.stdout); res=d.get("result",d); print(key,t["id"],res.get("stage"),res.get("launch",{}).get("effective"))
